<?php declare(strict_types=1);namespace NpmGateway\Http\Controllers;use NpmGateway\Contracts\CorporateToolsProviderInterface;use NpmGateway\Exceptions\Domain\{CommunityActionPropertyForbiddenException,CommunityActionPropertyNotFoundException,InvalidSupplyOrderException};use NpmGateway\Http\{AuthenticatedRequestContext,Request,Response};use NpmGateway\Security\CsrfService;use NpmGateway\Services\{CommunityActionContextResolver,SupplyOrderService};use NpmGateway\Support\FlashSession;
final readonly class SupplyOrderController{public function __construct(private CommunityActionContextResolver$resolver,private SupplyOrderService$service,private CorporateToolsProviderInterface$tools,private CsrfService$csrf,private FlashSession$flash,private string$views){}
 public function index(string$slug,AuthenticatedRequestContext$c):Response{if(($context=$this->context($c,$slug))instanceof Response)return$context;$orders=$this->service->listForProperty($context->propertyId);return$this->render('index',$c,compact('context','orders'));}
 public function create(string$slug,AuthenticatedRequestContext$c):Response{if(($context=$this->context($c,$slug))instanceof Response)return$context;$input=(array)$this->flash->pull('supply_order_input',[]);$errors=(array)$this->flash->pull('supply_order_errors',[]);return$this->render('create',$c,compact('context','input','errors'));}
 public function store(Request$r,string$slug,AuthenticatedRequestContext$c):Response{if(($context=$this->context($c,$slug))instanceof Response)return$context;if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.',['Cache-Control'=>'private, no-store']);try{$result=$this->service->submit($context,$r->post);$this->flash->put('supply_order_success','Supply order submitted successfully.');if(!$result['email_sent'])$this->flash->put('supply_order_warning','The supply order was saved, but the notification could not be delivered.');return Response::redirect('/community-actions/'.$slug.'/supply-orders/'.$result['public_id']);}catch(InvalidSupplyOrderException$e){$this->flash->put('supply_order_input',$e->input);$this->flash->put('supply_order_errors',$e->errors);return Response::redirect('/community-actions/'.$slug.'/supply-orders/create');}}
 public function show(string$slug,string$public,AuthenticatedRequestContext$c):Response{if(($context=$this->context($c,$slug))instanceof Response)return$context;$order=$this->service->detailForProperty($public,$context->propertyId);if(!$order)return new Response(404,'Not Found',['Cache-Control'=>'private, no-store']);$success=(string)$this->flash->pull('supply_order_success','');$warning=(string)$this->flash->pull('supply_order_warning','');return$this->render('show',$c,compact('context','order','success','warning'));}
 private function context(AuthenticatedRequestContext$c,string$slug):mixed{try{return$this->resolver->resolve($c,$slug);}catch(CommunityActionPropertyNotFoundException){return new Response(404,'Not Found');}catch(CommunityActionPropertyForbiddenException){return new Response(403,'Forbidden');}}private function render(string$view,AuthenticatedRequestContext$c,array$vars):Response{$user=$c->user;$csrfToken=$this->csrf->token();$logoutCsrfToken=$csrfToken;$navbarCorporateItems=$this->tools->tools($c);extract($vars);ob_start();require$this->views.'/community-actions/supply-orders/'.$view.'.php';return new Response(200,(string)ob_get_clean(),['Cache-Control'=>'private, no-store']);}
}
